/// <summary>
/// refresh datasources
/// </summary>
public void refreshDataSources()
{
    NDXRequisitionLine_ds.research();
    NDXRequisitionLineGrp_ds.research();
}

public void init()
{
    super();
    this.query().dataSourceName(this.name()).addSortField(fieldNum(NDXRequisition, RequisitionId), SortOrder::Descending);
}

public void init()
{
    super();
    this.query().dataSourceName(this.name()).addSortField(fieldNum(NDXRequisitionLine, Level));
    this.query().dataSourceName(this.name()).addSortField(fieldNum(NDXRequisitionLine, LevelString));
}

public void clicked()
{
    if(NDXRequisition.RecId == 0 && NDXRequisition.RequisitionId)
    {
        NDXRequisition.write();
    }

    if(!NDXRequisition.RecId)
    {
        throw error("@NDX:NDXRequisitionNotExists");
    }

    super();
}

public void clicked()
{
    if(NDXRequisition.RecId == 0 && NDXRequisition.RequisitionId)
    {
        NDXRequisition.write();
    }

    //super();
    Args args = new Args();
    NDXRequisitionExcelDMFImport dmfImport = NDXRequisitionExcelDMFImport::construct(NDXRequisition);

    args.parmObject(dmfImport);

    new MenuFunction(menuItemActionStr(NDXExcelDMFImport), MenuItemType::Action).run(args);
    element.refreshDataSources();
}
